  async function mutation(path, body = {}, button) { if (button) button.disabled = true; try { const data = await api(path, { method: 'POST', body }); setStatus(tr('تم حفظ العملية.', 'Operation saved.')); return data; } finally { if (button) button.disabled = false; } }
  async function ownerOperationalConfirm(title) {
    if(state.user?.role!=='owner')throw new Error(tr('للمالك فقط.','Owner only.'));
    if(!window.confirm(title+'\n'+tr('تأكيد الحفظ والاعتماد؟ يُسجّل الإجراء باسمك.','Confirm saving and approval? This action is recorded under your name.')))
      throw new Error(tr('أُلغي الحفظ؛ بياناتك باقية.','Save cancelled; your entries are retained.'));
  }
  async function ownerStepUp(password) {
    if (!state.user?.employee_sms_email_retired) return mutation('/api/identity/step-up', {password:password || ''});
    let sent=null;
    return new Promise((resolve, reject) => {
      const dialog = document.createElement('dialog');
      dialog.innerHTML = `<form><h2>${esc(tr('تحقق المالك برسالة SMS','Owner SMS verification'))}</h2><p>${esc(tr('أدخل الرمز المرسل إلى جوالك المسجل. صالح لخمس دقائق ولمرة واحدة.','Enter the code sent to your registered mobile. Valid once for five minutes.'))}</p><label>${esc(tr('رمز من 4 أرقام','Four-digit code'))}<input name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="4" required dir="ltr"></label><p class="form-error" role="alert"></p><button type="submit">${esc(tr('تحقق','Verify'))}</button><button type="button" data-cancel>${esc(tr('إلغاء','Cancel'))}</button></form>`;
      const retry=document.createElement('button');retry.type='button';retry.textContent=tr('إعادة إرسال رمز التحقق','Resend verification code');dialog.querySelector('form').append(retry);
      const verify=dialog.querySelector('[type=submit]');verify.disabled=true;
      const send=async()=>{retry.disabled=true;verify.disabled=true;try{
        const result=await api('/api/identity/owner/sms/request',{method:'POST'});
        if(!dialog.isConnected)return;sent=result;dialog.querySelector('.form-error').textContent='';verify.disabled=false;
      }catch(error){if(dialog.isConnected)dialog.querySelector('.form-error').textContent=error.message+' '+tr('لم يتم حفظ التعديل. بياناتك باقية؛ أعد الإرسال عند توفر الخدمة.','The change was not saved. Your entries remain; resend when the service is available.');}
      finally{if(dialog.isConnected)retry.disabled=false;}};
      retry.onclick=send;
      let settled=false;
      const finish=(error,result)=>{if(settled)return;settled=true;dialog.close();dialog.remove();error?reject(error):resolve(result);};
      dialog.addEventListener('cancel',e=>{e.preventDefault();finish(new Error(tr('أُلغي التحقق.','Verification cancelled.')));});
      dialog.querySelector('[data-cancel]').onclick=()=>finish(new Error(tr('أُلغي التحقق.','Verification cancelled.')));
      dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();if(!sent)return;const button=dialog.querySelector('[type=submit]');button.disabled=true;try{const result=await api('/api/identity/owner/sms/verify',{method:'POST',body:{challenge_id:sent.challenge_id,code:dialog.querySelector('[name=code]').value}});finish(null,result);}catch(error){dialog.querySelector('.form-error').textContent=error.message;}finally{button.disabled=false;}};
      document.body.append(dialog);dialog.showModal();send();dialog.querySelector('[name=code]').focus();
    });
  }
