  async function branchPrinters(branchId=null){await loadBranches();state.printerBranch=branchId;modal(tr('طابعات الفروع','Branch printers'),`<div class="stack"><p>${esc(tr('١. اختر الفرع  ٢. اربط الطابعة  ٣. اطبع اختبارًا  ٤. اعتمد','1. Select branch  2. Connect printer  3. Print test  4. Approve'))}</p><label>${esc(tr('الفرع','Branch'))}<select id="printer-branch"><option value="">${esc(tr('كل الفروع','All branches'))}</option>${selectOptions(state.branches,branchId||'',b=>branchLabel(b))}</select></label><button data-action="pair-printer">${esc(tr('إعداد ربط جديد','Set up new connection'))}</button><div id="printer-live">${esc(tr('جاري تحديث الحالة…','Updating status…'))}</div></div>`);$('#printer-branch').addEventListener('change',e=>branchPrinters(e.target.value||null));const root=$('#printer-live');let busy=false;async function refresh(){if(busy||!root.isConnected||!$('#modal').open)return;busy=true;try{const [d,j,m]=await Promise.all([api('/api/printing/devices'),api('/api/printing/jobs'),api('/api/printing/migration-status')]);if(!root.isConnected)return;root.innerHTML=printerRows(d.devices||[],branchId)+printerMigration(m,branchId)+table([tr('اختبار الطابعة','Printer test'),tr('الحالة','Status'),tr('الاعتماد','Approval')],(j.jobs||[]).filter(x=>x.kind==='test'&&(!branchId||x.branch_id===branchId)&&(d.devices||[]).some(v=>v.id===x.device_id&&v.acceptance_job_id===x.id&&!v.revoked_at&&!v.approved_at)).map(x=>[esc(branchLabel(x.branch_id)),esc(printStatus(x.status)),x.status==='submitted'?`<button data-action="approve-printer" data-id="${esc(x.device_id)}" data-job="${esc(x.id)}">${esc(tr('خرجت الورقة — اعتماد ✓','Paper printed — approve ✓'))}</button>`:esc(tr('بانتظار نتيجة الاختبار','Awaiting test result'))]))+table([tr('وقت الإرسال','Requested'),tr('الفرع','Branch'),tr('الفاتورة','Receipt'),tr('الحالة','Status')],(j.jobs||[]).filter(x=>x.kind!=='test'&&(!branchId||x.branch_id===branchId)).map(x=>[esc(datetime(x.created_at)),esc(branchLabel(x.branch_id)),esc(x.kind==='order'?tr('طلب','Order'):tr('تحضير','Preparation')),esc(printStatus(x.status))+(x.order_id&&['owner','delivery_manager'].includes(state.user.role)?` <button data-action="order-detail" data-id="${esc(x.order_id)}">${esc(tr('فتح الطلب / إعادة الطباعة','Open order / reprint'))}</button>`:'')]));}catch(e){if(root.isConnected)root.textContent=e.message;}finally{busy=false;}}await refresh();printerRefresh=setInterval(refresh,5000);}
  async function pairPrinter(){await loadBranches();const selected=state.printerBranch||'';modal(tr('ربط طابعة فرع','Connect branch printer'),`<form><label>${esc(tr('الفرع','Branch'))}<select name="branch_id" required><option value="">${esc(tr('اختر الفرع أولاً','Select branch first'))}</option>${selectOptions(state.branches,selected,b=>branchLabel(b))}</select></label>${field(tr('اسم الكمبيوتر','Computer name'),'label','',{required:true})}${field(tr('سبب الربط أو التعديل','Setup reason'),'reason',tr('إعداد طابعة الفرع','Branch printer setup'),{required:true})}<label>${esc(tr('عرض الورق','Paper width'))}<select name="paper_mm"><option value="80">80 mm</option><option value="58">58 mm</option></select></label>${notice(tr('نزّل الإعداد على كمبيوتر الفرع. فك الضغط وافتح Start.cmd، ثم اختر الطابعة من القائمة واضغط ربط. الملف صالح لعشر دقائق ولمرة واحدة.','Download on the branch computer. Extract, open Start.cmd, select a printer and connect. Valid for ten minutes and one use.'))}${formEnd(tr('تنزيل إعداد الفرع','Download branch setup'))}</form>`,async fd=>{const branch=fd.get('branch_id');const d=await api('/api/printing/setup',{method:'POST',body:{branch_id:branch,label:fd.get('label'),reason:fd.get('reason'),paper_mm:Number(fd.get('paper_mm'))}});const bytes=Uint8Array.from(atob(d.bundle),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:'application/zip'}));const a=document.createElement('a');a.href=url;a.download='KPS-Branch-Setup.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);await branchPrinters(branch);setStatus(tr('تم تنزيل الإعداد: فك الضغط على كمبيوتر الفرع وافتح Start.cmd.','Setup downloaded: extract on the branch computer and open Start.cmd.'));});}

