  async function renderDriverTripPanel(shift,tasksList) {
    const host=document.createElement('section');host.className='panel driver-trip-panel';host.setAttribute('aria-live','polite');
    $('#content').prepend(host);
    try {
      const result=await api('/api/driver-work-hours/current');
      const trip=result.trip;
      if(!trip&&(!shift||shift.status!=='open')){host.remove();return;}
      const scope=state.branches.filter(b=>(state.user.branch_ids||[]).includes(b.id)&&(shift?.branch_ids||[]).includes(b.id));
      const picked=tasksList.filter(t=>t.driver_id===state.user.id&&t.shift_id===shift?.id&&t.status==='picked_up');
      const departureBranches=scope.filter(b=>picked.some(t=>t.branch_id===b.id));
      const branches=trip?scope:departureBranches;
      host.innerHTML=`<h2>${esc(trip?tr('بانتظار تأكيد العودة','Awaiting return confirmation'):tr('رحلة التوصيل','Delivery trip'))}</h2>${trip?`<p>${esc(branchLabel(trip.departure_branch_id))} · ${esc(datetime(trip.departed_at))}</p>${notice(tr('تستمر الرحلة حتى تؤكد العودة للفرع، حتى بعد تسليم آخر طلب.','The trip remains open until you confirm returning to a branch, including after the last delivery.'))}`:notice(tr('استلم الطلبات أولًا، ثم أكّد الخروج من الفرع. الطلبات في الرحلة الواحدة لا تضاعف الوقت.','Pick up orders first, then confirm leaving the branch. Multiple orders in one trip count time once.'))}${branches.length?`<form class="driver-trip-form"><label>${esc(trip?tr('فرع العودة الفعلي','Actual return branch'):tr('فرع الانطلاق','Departure branch'))}<select name="branch_id" required>${branches.map(b=>`<option value="${esc(b.id)}">${esc(branchLabel(b))}</option>`).join('')}</select></label>${trip?'':'<div class="driver-trip-orders"></div>'}<p class="form-error" role="alert"></p><button type="submit">${esc(trip?tr('عدت إلى الفرع','I returned to the branch'):tr('خرجت من الفرع بالطلبات','I left the branch with these orders'))}</button></form>`:notice(tr('لا توجد طلبات مستلمة مؤهلة لبدء رحلة.','No eligible picked-up orders are available to start a trip.'))}`;
      const form=host.querySelector('form');if(!form)return;
      const branchInput=form.elements.branch_id;
      const renderOrders=()=>{if(trip)return;form.querySelector('.driver-trip-orders').innerHTML=picked.filter(t=>t.branch_id===branchInput.value).map(t=>`<label><input type="checkbox" name="order_id" value="${esc(t.order_id)}" checked> ${esc(orderLabel({...t.snapshot,...t,id:t.order_id}))}</label>`).join('');};
      branchInput.addEventListener('change',renderOrders);renderOrders();
      form.addEventListener('submit',async event=>{
        event.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;
        try {
          const fd=new FormData(form),branch_id=String(fd.get('branch_id'));
          const body=trip?{branch_id}:{branch_id,shift_id:shift.id,order_ids:fd.getAll('order_id')};
          if(!trip&&!body.order_ids.length)throw new Error(tr('اختر طلبًا مستلمًا واحدًا على الأقل.','Select at least one picked-up order.'));
          if(navigator.geolocation){const location=await new Promise(resolve=>navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lng:p.coords.longitude}),()=>resolve(null),{enableHighAccuracy:true,timeout:5000,maximumAge:15000}));if(location)Object.assign(body,location);}
          await mutation(trip?'/api/driver-work-hours/'+encodeURIComponent(trip.id)+'/return':'/api/driver-work-hours/depart',body);
          setStatus(trip?tr('تم تسجيل العودة للفرع.','Branch return recorded.'):tr('تم تسجيل بداية الرحلة.','Trip departure recorded.'));
          await loadPage();
        }catch(error){form.querySelector('.form-error').textContent=error.message;}finally{button.disabled=false;}
      });
    }catch(error){host.innerHTML=notice(tr('تعذر تحميل حالة الرحلة: ','Trip status could not be loaded: ')+error.message,'warn');}
  }
