  let inboxPolling=false;
  async function pollInbox(){
    const root=$('.conversation-list'),user=state.user?.id;
    if(inboxPolling||state.page!=='chat'||!root)return;
    inboxPolling=true;
    try{const d=await api('/api/conversations');if(state.page!=='chat'||root!==$('.conversation-list')||state.user?.id!==user)return;const rows=d.conversations||[],signature=JSON.stringify([rows,state.selectedConversation,state.lang]);if(root.dataset.signature===signature||root.contains(document.activeElement))return;const top=root.scrollTop;root.innerHTML=rows.map(conversationCard).join('')||empty(tr('لا توجد محادثات.','No conversations.'));root.dataset.signature=signature;root.scrollTop=top;state.conversations=rows;}catch{}finally{inboxPolling=false;}
  }
  let conversationPolling=false;
  async function pollConversation(){if(trialMode)return;
    const root=$('#chat-detail'),id=state.selectedConversation,version=conversationVersion;
    if(conversationPolling||!chatSurfaceActive()||!id||root?.dataset.conversation!==id)return;
    conversationPolling=true;
    try{
      const previous=state.chatHistory.get(id)||[],after=previous.at(-1)?.seq||0;
      const d=await api(`/api/conversations/${encodeURIComponent(id)}/messages?after=${after}`);
      if(!chatSurfaceActive()||state.selectedConversation!==id||version!==conversationVersion||root!==$('#chat-detail'))return;
      const box=$('#messages',root);if(!box)return;const error=$('.form-error',root);if(error?.dataset.pollFailed){error.textContent='';delete error.dataset.pollFailed;}
      const bottom=box.scrollHeight-box.scrollTop-box.clientHeight<60,top=box.scrollTop;
      const rows=d.messages||[],fresh=rows.filter(m=>!previous.some(p=>p.id===m.id));
      if(fresh.length){if(!previous.length)box.replaceChildren();box.insertAdjacentHTML('beforeend',fresh.map(messageMarkup).join(''));state.chatHistory.set(id,[...previous,...fresh]);box.scrollTop=bottom?box.scrollHeight:top;}
      const more=$('[data-action="more-messages"]',root);
      if(more){more.dataset.after=String((state.chatHistory.get(id)||[]).at(-1)?.seq||after);if(rows.length<100)more.remove();}
      const seq=(state.chatHistory.get(id)||[]).at(-1)?.seq;
      if(bottom&&seq&&root.dataset.readSeq!==String(seq)){await api(`/api/conversations/${encodeURIComponent(id)}/read`,{method:'POST',body:{through_seq:seq}});if(root.isConnected)root.dataset.readSeq=String(seq);}
    }catch(e){if(root?.isConnected&&chatSurfaceActive()){const error=$('.form-error',root);if(error&&!error.textContent){error.textContent=tr('تعذر تحديث الرسائل مؤقتًا؛ ستتم إعادة المحاولة تلقائيًا.','Messages could not refresh; retrying automatically.');error.dataset.pollFailed='true';}}}finally{conversationPolling=false;}
  }

  async function imageUpload(path,file,extra={}) { if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw new Error(tr('اختر صورة JPEG أو PNG أو WebP لا تتجاوز 5 MB.','Choose a JPEG, PNG or WebP image up to 5 MB.')); const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(new Error(tr('تعذر قراءة الصورة.','Could not read the image.')));r.readAsDataURL(file);});return mutation(path,{...extra,data_base64:data,content_type:file.type}); }

  function photoTransition(id,stage){
    let photoId=null,previewUrl=null;
    modal(tr(stage==='picked_up'?'صورة الاستلام من الفرع':'صورة تسليم الطلب',stage==='picked_up'?'Branch pickup photo':'Delivery photo'),`<form>
      <p>${esc(tr('صورة إلزامية — الطلب فقط، تجنب تصوير الأشخاص','Required photo — photograph the order, avoid people'))}</p>
      <div class="actions"><button type="button" id="task-photo-camera">${esc(tr('فتح الكاميرا','Open camera'))}</button><button type="button" class="quiet" id="task-photo-gallery">${esc(tr('اختيار من الاستديو','Choose from gallery'))}</button></div>
      <label>${esc(tr('الصورة — يمكنك اختيارها هنا إذا لم تفتح الكاميرا','Photo — choose it here if the camera does not open'))}<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" capture="environment" required></label>
      <img id="task-photo-preview" hidden alt="${esc(tr('معاينة صورة الطلب','Order photo preview'))}" style="max-width:100%;max-height:240px;object-fit:contain">
      ${textarea(tr('ملاحظة اختيارية','Optional note'),'proof','')}${formEnd(tr('حفظ الصورة وتأكيد الخطوة','Save photo and confirm'))}</form>`,async(fd)=>{
      const file=fd.get('photo');
      if(!photoId){if(!file?.size)throw new Error(tr('أضف الصورة أولاً','Add a photo first'));photoId=(await imageUpload(`/api/tasks/${encodeURIComponent(id)}/photos`,file,{stage})).id;}
      await mutation(`/api/tasks/${encodeURIComponent(id)}/transition`,{status:stage,photo_id:photoId,proof:fd.get('proof')||''});closeModal();await loadPage();
    });
    const input=$('#modal-body [name=photo]'),preview=$('#task-photo-preview');
    const releasePreview=()=>{if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=null;};
    const choosePhoto=camera=>{
      if(camera)input.setAttribute('capture','environment');else input.removeAttribute('capture');
      // A synchronous native picker request retains the initiating user gesture.
      // Browsers without capture support use their normal file chooser instead.
      try{input.click();}catch(_){input.focus();}
    };
    $('#task-photo-camera').addEventListener('click',()=>choosePhoto(true));
    $('#task-photo-gallery').addEventListener('click',()=>choosePhoto(false));
    input.addEventListener('change',()=>{
      photoId=null;releasePreview();const file=input.files[0];preview.hidden=!file;
      if(file){previewUrl=URL.createObjectURL(file);preview.src=previewUrl;}else preview.removeAttribute('src');
    });
    $('#modal').addEventListener('close',releasePreview,{once:true});
    choosePhoto(true);
  }
