    const labels={unconfigured:tr('النسخ الاحتياطي غير مهيأ وغير متحقق منه.','Backups are unconfigured and unverified.'),unverified:tr('توجد إعدادات مزود، لكن النسخ الاحتياطي لم يُتحقق منه.','Provider settings exist, but backups are unverified.'),attention_required:tr('توجد تنبيهات فشل محفوظة تحتاج مراجعة المالك.','Persistent failure alerts require owner review.'),observed:tr('رُصد حدث من المزود؛ نجاح الاسترجاع لم يُثبت بذلك.','A provider event was observed; this does not prove a successful restore.'),unavailable:tr('تعذر قراءة حالة النسخ؛ لا توجد حالة نجاح مؤكدة.','Backup status could not be read; no success is confirmed.')};
    const unknown=tr('غير متحقق منه','Unverified'),source={none:tr('لا يوجد تحقق من المزود','No provider verification'),signed_webhook:tr('حدث مزود بتوقيع متحقق منه','Verified signed provider event'),provider_api:tr('قراءة فعلية من واجهة المزود','Actual provider API observation')}[r.verification_source]||unknown;
    const seconds=value=>value==null?unknown:`${num(value)} ${tr('ثانية','seconds')}`;
