    const labels={unavailable:tr('تعذر قراءة المراقبة','Monitoring unavailable'),unverified:tr('لم تسجل قراءة فعلية','No actual observation yet'),stale:tr('القراءة قديمة وتحتاج تحديثًا','Observation is stale'),attention_required:tr('توجد أعطال تحتاج مراجعة','Failures need review'),observed:tr('قراءة فعلية محفوظة','Actual observation recorded')};
    const checks={runtime_server_errors:tr('أخطاء الخادم','Server errors'),runtime_database_latency:tr('بطء قاعدة البيانات','Database latency'),runtime_email_delivery_failed:tr('فشل إرسال البريد','Email send failure'),runtime_email_queue_stalled:tr('تراكم البريد المنتظر','Mail queue stalled'),runtime_backup_observation_stale:tr('عدم وجود رصد حديث للنسخ الاحتياطي','No recent backup observation'),runtime_memory_pressure:tr('ضغط الذاكرة','Memory pressure'),runtime_ephemeral_storage_pressure:tr('امتلاء التخزين المؤقت','Ephemeral storage pressure'),runtime_database_storage_pressure:tr('امتلاء تخزين قاعدة البيانات','Database storage pressure')};
