    modal(tr('إصدار الفواتير الضريبية','Tax invoice issuance'),`<form>${notice(cfg.issuance_enabled?tr('إصدار الفواتير مفعل لجميع فروع كبز المسجلة. حالة الربط بالهيئة مستقلة عن إصدار الفاتورة.','Invoice issuance is enabled for all registered KPS branches. Authority integration is separate from invoice issuance.'):tr('الإصدار الرسمي متوقف. معاينة الفاتورة لا تعني إصدارها.','Official issuance is disabled. A preview is not an issued invoice.'))}<label>${esc(tr('المرحلة النظامية الموثقة','Documented applicable phase'))}<select name="phase">${[['unconfirmed',tr('لم يتم التحقق','Unconfirmed')],['phase1',tr('المرحلة الأولى','Phase 1')],['phase2',tr('المرحلة الثانية','Phase 2')]].map(([v,label])=>`<option value="${v}" ${d.phase===v?'selected':''}>${esc(label)}</option>`).join('')}</select></label>${textarea(tr('مرجع إثبات المرحلة المنطبقة','Applicable-phase evidence reference'),'evidence_reference',d.evidence_reference||'')}${notice(tr('المرحلة الثانية تحتاج الربط والتوقيع النظامي، ولا يمكن تفعيلها في هذا الإصدار. تحديد المرحلة يجب أن يستند إلى إشعار الهيئة وملف المنشأة.','Phase 2 needs regulatory integration and signing and cannot be enabled in this release. Determine applicability from the authority notification and business records.'),'warn')}${check(tr('إصدار الفواتير بقرار المالك مع بقاء المرحلة غير متحققة — دون ادعاء الربط بالهيئة','Owner-requested issuance with unconfirmed applicability — no claim of authority integration'),'owner_requested',d.issuance_mode==='owner_requested')}${check(tr('تفعيل إصدار الفواتير لجميع الفروع المسجلة','Enable invoice issuance for all registered branches'),'enabled',cfg.issuance_enabled)}${textarea(tr('سبب القرار','Decision reason'),'reason','',true)}${formEnd(tr('حفظ قرار المالك','Save owner decision'))}</form>`,async fd=>{
      await mutation('/api/fiscal/policy',{issuance_mode:fd.has('owner_requested')?'owner_requested':'verified_phase1',phase:fd.get('phase'),enabled:fd.has('enabled'),evidence_reference:fd.get('evidence_reference'),reason:fd.get('reason'),expected_policy_id:cfg.policy_id});closeModal();await loadPage();
    });
