  async function printOrder(id, preparation=false, fiscalPreview=false) {
    const win=window.open('','_blank');if(!win)throw new Error(tr('اسمح بنافذة الطباعة لهذا الموقع.','Allow the print window for this site.'));win.opener=null;
    try{
      const d=fiscalPreview?await mutation(`/api/fiscal/orders/${encodeURIComponent(id)}/preview`,{}):preparation?await api(`/api/orders/${encodeURIComponent(id)}`):await mutation(`/api/fiscal/orders/${encodeURIComponent(id)}/print`,{}),o=normalizeOrder(!preparation&&d.order.issued_receipt?{...d.order,...d.order.issued_receipt}:d.order);
      win.document.write(receiptHTML(o,preparation,fiscalPreview||o.fiscal_document?state.lang:'en'));win.document.close();
      bindReceiptWindow(win);
    }catch(error){win.close();throw error;}
  }
