  async function managerHandover(id) { const d=await api('/api/shifts/current');const list=(d.available_manager_shifts||[]).filter(s=>s.id!==id&&s.user_id!==state.user.id);modal(tr('تسليم مسؤولية المناوبة','Hand over shift responsibility'),`<form><label>${esc(tr('شفت المدير المستلم','Receiving manager shift'))}<select name="target_manager_shift_id" required><option value="">${esc(tr('اختر المدير المستلم','Choose receiving manager'))}</option>${selectOptions(list,'',s=>`${s.display_name} · ${shiftLabel(s)}`)}</select></label>${textarea(tr('سبب التسليم والسياق التشغيلي','Handover reason and operational context'),'reason','',true)}${notice(tr('تتجمد المناوبة للإسناد الجديد ويقبل المدير المستلم المسؤولية من حسابه. النقد يُسلم ويُؤكد بإجراء مستقل.','New assignments are frozen; the receiving manager accepts responsibility from their account. Cash handover and confirmation remain separate.'))}${formEnd(tr('اقتراح تسليم المناوبة','Propose shift handover'))}</form>`,async(fd)=>{await mutation(`/api/shifts/${encodeURIComponent(id)}/handover-manager`,{target_manager_shift_id:fd.get('target_manager_shift_id'),reason:fd.get('reason')});closeModal();await loadPage();}); }
