  async function refundOrder(id) { const d=await api(`/api/orders/${encodeURIComponent(id)}`),o=normalizeOrder(d.order);const shifts=await api('/api/shifts/current');const q={};for(const i of o.items)q[i.product_id]={name:i.name,quantity:(q[i.product_id]?.quantity||0)+i.quantity};modal(tr('استرداد مأذون مرتبط بالطلب','Authorized order refund'),`<form class="form-columns">${notice(tr('سجّل الاسترداد الفعلي للعميل. لا يعدّل تقفيلة تاريخية؛ الاسترداد النقدي يحتاج عهدة شفت مفتوح كافية.','Record the actual customer refund. Historical closures stay immutable; cash refunds require sufficient custody in an open shift.'),'warn')}${amountField(tr('مبلغ الاسترداد بالريال','Refund amount (SAR)'),'amount',0)}<label>${esc(tr('طريقة التحصيل الأصلية','Original collection method'))}<select name="refund_method">${(o.payment_method==='split'?['cash','card']:[o.payment_method]).map(m=>`<option value="${esc(m)}">${esc(m==='cash'?tr('كاش','Cash'):tr('شبكة','Card'))}</option>`).join('')}</select></label><label class="full">${esc(tr('شفت العهدة الذي يصرف الاسترداد','Custody shift funding the refund'))}<select name="shift_id"><option value="">${esc(tr('شفت التحصيل الأصلي، إن كان مفتوحًا','Original collection shift, if open'))}</option>${selectOptions((shifts.shifts||[]).filter(s=>['open','closing'].includes(s.status)),'',s=>`${s.display_name} · ${shiftLabel(s)}`)}</select></label><fieldset class="full"><legend>${esc(tr('كميات الأصناف المستردة فعليًا','Actual refunded item quantities'))}</legend><div class="form-columns">${Object.entries(q).map(([pid,i])=>field(`${i.name} · ${tr('الحد الأصلي','Original maximum')}: ${i.quantity}`,`quantity:${pid}`,0,{type:'number',min:0,step:1})).join('')}</div></fieldset>${textarea(tr('سبب الاسترداد ومرجعه الفعلي','Refund reason and actual reference'),'reason','',true)}${check(tr('أُعيد المبلغ للعميل فعليًا','The amount was actually refunded to the customer'),'confirmed')}${formEnd(tr('اعتماد وحفظ الاسترداد','Authorize and save refund'))}</form>`,async fd=>{if(!fd.has('confirmed'))throw new Error(tr('أكد الاسترداد الفعلي للعميل.','Confirm the actual customer refund.'));const line_quantities={};for(const pid of Object.keys(q)){const n=Number(fd.get(`quantity:${pid}`));if(!Number.isInteger(n)||n<0||n>q[pid].quantity)throw new Error(tr('كمية الاسترداد غير صحيحة.','Invalid refund quantity.'));if(n)line_quantities[pid]=n;}await mutation(`/api/orders/${encodeURIComponent(id)}/refund`,{amount_halalas:cents(fd.get('amount')),method:fd.get('refund_method'),reason:fd.get('reason'),line_quantities,shift_id:fd.get('shift_id')||null});closeModal();await loadPage();}); }
  function cashEvent(id) { modal(tr('قيد عهدة مأذون — المالك','Authorized custody entry — owner'),`<form class="form-columns"><label>${esc(tr('نوع القيد','Entry type'))}<select name="kind"><option value="direct_receipt">${esc(tr('استلام مباشر مأذون','Authorized direct receipt'))}</option><option value="expense">${esc(tr('مصروف مأذون من العهدة','Authorized custody expense'))}</option><option value="adjustment">${esc(tr('تصحيح مرتبط بسجل','Linked correction'))}</option></select></label>${amountField(tr('المبلغ بالريال','Amount (SAR)'),'amount',0)}<label>${esc(tr('اتجاه التصحيح فقط','Correction direction only'))}<select name="sign"><option value="1">${esc(tr('إضافة إلى العهدة','Increase custody'))}</option><option value="-1">${esc(tr('طرح من العهدة','Decrease custody'))}</option></select></label>${field(tr('مرجع القيد المرتبط','Linked entry reference'),'reference','',{required:true})}${textarea(tr('سبب الاعتماد','Approval reason'),'reason','',true)}${check(tr('أقر القيد الفعلي وأثره في الرصيد','I approve the actual entry and its balance impact'),'confirmed')}${formEnd(tr('اعتماد وحفظ القيد','Authorize and save entry'))}</form>`,async fd=>{if(!fd.has('confirmed'))throw new Error(tr('أكد اعتماد القيد.','Confirm entry approval.'));const kind=fd.get('kind');let amount=cents(fd.get('amount'));if(kind==='expense')amount=-amount;else if(kind==='adjustment')amount*=Number(fd.get('sign'));await mutation(`/api/shifts/${encodeURIComponent(id)}/cash-event`,{kind,amount_halalas:amount,reason:fd.get('reason'),reference:fd.get('reference')});closeModal();await loadPage();}); }
